// HudKit.h -- the shared HUD art kit of queue-hud and companion-selfheal (doc 24 CS11/CS12): one source of truth for the slot frame,
// the Cancel X and the backing disc, plus the colours they are drawn with.
//
//   kit_frame / kit_frame_hi    64x64 rounded slot tile (hotbar recipe), border (0,44,26) / (208,204,170), centre fill alpha 175
//   kit_cancel / kit_cancel_hi  64x64 frame + shaded X glyph
//   kit_disc                    48x48 round backing disc, (0,0,0,175) fill, 2 px (10,96,80) rim
//
// The pixels live in HudKitTextures.inc (GENERATED by scripts/gen_hud_kit_textures.py, pixel-identical to the former qh_* / csh_disc
// arrays). This header wraps the EmbedTex.h loading pattern the mods already used: the mod sets embtex::g_log, calls hudkit::ensure() once
// per process (create + fill + queue; idempotent) and embtex::heal() every frame (the kit textures are part of embtex's remembered set), then
// asks for the pooled GUI image with frame(hover) / cancel(hover) / disc(). An image getter returns nullptr when the texture is unavailable (the
// caller falls back to its flat look / text X); call it only after ensure() (a failed lookup is not pooled: each call retries until the texture exists).
//
// Both mods embed their own copy of the arrays (each DLL has its own embtex slot set); the resrefs are shared names. embtex::MaxTex (16)
// must hold the mod's own textures plus Count (5).
#pragma once
#include "EmbedTex.h"
#include "GuiKit.h"

namespace hudkit {

namespace detail {
#include "HudKitTextures.inc"
}

enum Id : int { Frame = 0, FrameHi, Cancel, CancelHi, Disc, Count };   // order of the embedded array (and of the generator's output)
static_assert(sizeof detail::kHudKitTextures / sizeof detail::kHudKitTextures[0] == Count, "kit_frame, kit_frame_hi, kit_cancel, kit_cancel_hi, kit_disc");

struct Rgb { int r, g, b; };
constexpr Rgb kBorder{ 0, 44, 26 };      // frame border / hotbar slot green
constexpr Rgb kHi{ 208, 204, 170 };      // hover / highlight beige border
constexpr Rgb kAccent{ 10, 96, 80 };     // teal accent (disc rim, wrench-family glyph shade)
constexpr int kFillAlpha = 175;          // centre fill alpha of frame / disc (0..255)

inline const embtex::Tex* textures() { return detail::kHudKitTextures; }   // Count entries, in Id order
inline const char* resref(int id) { return id >= 0 && id < Count ? detail::kHudKitTextures[id].resref : ""; }

// Create + fill + queue the kit textures (EmbedTex ensure(): idempotent, Steam-only). Set embtex::g_log first. True when all Count are filled.
inline bool ensure() { return embtex::ensure(detail::kHudKitTextures, Count); }

// Pooled GUI image handle of a kit texture (never released, which keeps the texture alive); nullptr until the texture exists.
inline void* image(int id) {
    static void* cache[Count] = {};
    if (id < 0 || id >= Count) return nullptr;
    if (!cache[id]) cache[id] = guikit::imageForRetry(detail::kHudKitTextures[id].resref);   // null is not pooled: retried until the texture exists (SH-3a-05)
    return cache[id];
}
inline void* frame(bool hover) { return image(hover ? FrameHi : Frame); }
inline void* cancel(bool hover) { return image(hover ? CancelHi : Cancel); }
inline void* disc() { return image(Disc); }

}  // namespace hudkit
